SELECT id, symbol, side, execution_reason, execution_key, executed_at FROM crypto_ai.wallet_trade WHERE executed_at BETWEEN '2026-10-11 20:59:30' AND '2026-10-11 21:00:30' OR executed_at BETWEEN '2026-10-11 22:42:30' AND '2026-10-11 22:44:00' OR executed_at BETWEEN '2026-10-12 03:29:30' AND '2026-10-12 03:30:30' OR executed_at BETWEEN '2026-10-12 07:14:30' AND '2026-10-12 07:16:00' OR executed_at BETWEEN '2026-10-12 10:04:30' AND '2026-10-12 10:05:40' ORDER BY executed_at LIMIT 100